import{o,c as n,a0 as r,j as t,t as s,a as l,p as d}from"./chunks/framework.L_oL6aia.js";const u={class:"rock-copy-email-wrapper inline"},p=JSON.parse('{"title":"Midnight Rambler: User Manual","description":"","frontmatter":{},"headers":[],"relativePath":"midnight-rambler.md","filePath":"midnight-rambler.md"}'),h={name:"midnight-rambler.md"},b=Object.assign(h,{setup(c){const i=d("Copy Email");function a(){navigator.clipboard.writeText("mainstaudiolabs@gmail.com"),i.value="Copied!",setTimeout(function(){i.value="Copy Email"},2e3)}return(m,e)=>(o(),n("div",null,[e[1]||(e[1]=r('<h1 id="midnight-rambler-user-manual" tabindex="-1">Midnight Rambler: User Manual <a class="header-anchor" href="#midnight-rambler-user-manual" aria-label="Permalink to &quot;Midnight Rambler: User Manual&quot;">​</a></h1><p>This manual provides a detailed description of the usage, design philosophy, and technical specifications for the <strong>Midnight Rambler</strong> amplifier emulation stompbox plugin.</p><img src="/mr.png" alt="Midnight Rambler GUI" style="max-height:240px;display:block;margin:1.5rem auto;border:2px solid var(--vp-c-border);"><hr><h2 id="_1-design-philosophy-the-simplicity-manifesto" tabindex="-1">1. Design Philosophy: The Simplicity Manifesto <a class="header-anchor" href="#_1-design-philosophy-the-simplicity-manifesto" aria-label="Permalink to &quot;1. Design Philosophy: The Simplicity Manifesto&quot;">​</a></h2><p><strong>Midnight Rambler</strong> is built upon a clear philosophy: <strong>deliver the bare minimum interface to maximize the sonic experience and touch-sensitive dynamics.</strong></p><p>Unlike conventional digital plugins that clutter the interface with endless options and nested menus, this pedal focuses on a single, meticulously calibrated tone that performs instantly.</p><h3 id="a-sound-designed-for-the-mix" tabindex="-1">A Sound Designed for the Mix <a class="header-anchor" href="#a-sound-designed-for-the-mix" aria-label="Permalink to &quot;A Sound Designed for the Mix&quot;">​</a></h3><p>The pedal is designed based on a deep study of Keith Richards&#39; legendary guitar tone. The virtual circuit has been optimized and adapted specifically to sit perfectly in the mix without requiring complex external EQ adjustments, shaving off muddy low-end and controlling harsh high-end.</p><h3 id="ultra-low-cpu-consumption" tabindex="-1">Ultra-Low CPU Consumption <a class="header-anchor" href="#ultra-low-cpu-consumption" aria-label="Permalink to &quot;Ultra-Low CPU Consumption&quot;">​</a></h3><p>Thanks to a highly optimized audio processing engine, the pedal delivers near-zero latency and extremely low CPU usage, guaranteeing an immediate and organic response to your playing dynamics.</p><hr><h2 id="_2-control-guide" tabindex="-1">2. Control Guide <a class="header-anchor" href="#_2-control-guide" aria-label="Permalink to &quot;2. Control Guide&quot;">​</a></h2><p>The pedal features simple yet high-precision controls to shape your tone:</p><h3 id="🎛️-1-gain-gain-boost" tabindex="-1">🎛️ 1. GAIN (Gain Boost) <a class="header-anchor" href="#🎛️-1-gain-gain-boost" aria-label="Permalink to &quot;🎛️ 1. GAIN (Gain Boost)&quot;">​</a></h3><ul><li><strong>Function:</strong> Controls the input gain before the saturation stage.</li><li><strong>Range:</strong> <code>-12.0 dB</code> to <code>+15.0 dB</code>.</li><li><strong>Usage:</strong><ul><li><strong>Low Values (-12 dB to 0 dB):</strong> Cleans up the signal, ideal for dynamic, clean-to-edge-of-breakup tones, especially with high-output humbucker pickups.</li><li><strong>High Values (0 dB to +15 dB):</strong> Pushes the virtual circuits into saturation, delivering a rich harmonic distortion, natural compression, and increased sustain.</li></ul></li></ul><h3 id="🎛️-2-bass-bass-cut-hp-filter" tabindex="-1">🎛️ 2. BASS (Bass Cut - HP Filter) <a class="header-anchor" href="#🎛️-2-bass-bass-cut-hp-filter" aria-label="Permalink to &quot;🎛️ 2. BASS (Bass Cut - HP Filter)&quot;">​</a></h3><ul><li><strong>Function:</strong> A post-saturation High-Pass Filter designed to sculpt the low-end.</li><li><strong>Range:</strong> <code>20.0 Hz</code> to <code>300.0 Hz</code> (logarithmic scale for finer control).</li><li><strong>Usage:</strong> Shaves off muddy low-end frequencies to keep the mix tight, without altering the natural breakup of the virtual valves. At its minimum value (20 Hz), the filter is fully open.</li></ul><h3 id="🎛️-3-tone-tone-cut-lp-filter" tabindex="-1">🎛️ 3. TONE (Tone Cut - LP Filter) <a class="header-anchor" href="#🎛️-3-tone-tone-cut-lp-filter" aria-label="Permalink to &quot;🎛️ 3. TONE (Tone Cut - LP Filter)&quot;">​</a></h3><ul><li><strong>Function:</strong> A post-saturation Low-Pass Filter designed to control treble presence.</li><li><strong>Range:</strong> <code>1.0 kHz</code> to <code>20.0 kHz</code>.</li><li><strong>Usage:</strong> Tames harshness and digital sibilance. Higher values deliver a modern, glassy bite, while lower values roll off the highs for a warm, dark, and rounded vintage tone.</li></ul><h3 id="🎛️-4-master-master-volume" tabindex="-1">🎛️ 4. MASTER (Master Volume) <a class="header-anchor" href="#🎛️-4-master-master-volume" aria-label="Permalink to &quot;🎛️ 4. MASTER (Master Volume)&quot;">​</a></h3><ul><li><strong>Function:</strong> Adjusts the final output level of the plugin.</li><li><strong>Range:</strong> <code>-60.0 dB</code> to <code>+6.0 dB</code>.</li><li><strong>Usage:</strong> Compensates the output level when raising the GAIN knob, protecting your monitors and controlling the signal level sent to your DAW track.</li></ul><h3 id="📻-5-mic-cab-mode-microphone-cabinet-selector" tabindex="-1">📻 5. MIC / CAB MODE (Microphone &amp; Cabinet Selector) <a class="header-anchor" href="#📻-5-mic-cab-mode-microphone-cabinet-selector" aria-label="Permalink to &quot;📻 5. MIC / CAB MODE (Microphone &amp; Cabinet Selector)&quot;">​</a></h3><p>Allows switching between three different cabinet acoustic profiles using real-time audio convolution:</p><ol><li><strong>WARM:</strong> A thick, full-bodied response with pronounced low-end and warm mids, ideal for greasy and fat rhythm playing.</li><li><strong>SHARP:</strong> Emulates a dynamic mic capsule with emphasized upper-mids and a natural low-end roll-off, providing a sharp attack that cuts cleanly through any mix.</li><li><strong>BLEND:</strong> A custom combined response (60% Shure SM57 and 40% Royer R121), delivering the perfect balance of dynamic bite and ribbon warmth for all-around playability.</li></ol><h3 id="🎛️-6-standby-mute-safe-switch" tabindex="-1">🎛️ 6. STANDBY (Mute / Safe Switch) <a class="header-anchor" href="#🎛️-6-standby-mute-safe-switch" aria-label="Permalink to &quot;🎛️ 6. STANDBY (Mute / Safe Switch)&quot;">​</a></h3><ul><li><strong>Function:</strong> Emulates the standby switch found on physical tube amplifiers, acting as a total mute switch.</li><li><strong>Usage:</strong> Silences the plugin&#39;s output. When active, it triggers an early return in the processing loop, dropping the plugin&#39;s CPU usage to <strong>0%</strong> instantly.</li></ul><hr><h2 id="_3-audio-configuration-standalone" tabindex="-1">3. Audio Configuration (Standalone) <a class="header-anchor" href="#_3-audio-configuration-standalone" aria-label="Permalink to &quot;3. Audio Configuration (Standalone)&quot;">​</a></h2><p>When running the pedal as a standalone application, configure your audio settings as follows for optimal performance:</p><ol><li><strong>Audio Device Type:</strong> Always select <strong>ASIO</strong> on Windows to avoid latency and digital distortion.</li><li><strong>Device:</strong> Select the native ASIO driver of your audio interface (e.g., <em>Focusrite USB ASIO</em>).</li><li><strong>Sample Rate:</strong> Set it to <strong>48000 Hz</strong> (48 kHz).</li><li><strong>Buffer Size:</strong> Set the buffer size to <strong>128 samples</strong> (2.3 ms) or <strong>256 samples</strong> (5.3 ms).</li></ol><h4 id="💡-the-buffer-phenomenon-why-256-samples-5-3-ms-might-sound-better-than-128-samples-2-3-ms" tabindex="-1">💡 The Buffer Phenomenon: Why 256 samples (5.3 ms) might sound better than 128 samples (2.3 ms) <a class="header-anchor" href="#💡-the-buffer-phenomenon-why-256-samples-5-3-ms-might-sound-better-than-128-samples-2-3-ms" aria-label="Permalink to &quot;💡 The Buffer Phenomenon: Why 256 samples (5.3 ms) might sound better than 128 samples (2.3 ms)&quot;">​</a></h4><p>Many guitarists experience a sweeter, more fluid tone at 256 samples. This is due to two factors:</p><ul><li><strong>Processor Stability:</strong> At 256 samples, the CPU processes audio chunks with more headroom, preventing micro-jitters that can introduce subtle treble harshness.</li><li><strong>Acoustic Duplication Effect:</strong> The tiny 5.3 ms delay, combined with the physical acoustic sound of your unplugged electric strings vibrating in the room, creates an organic doubling effect that adds tridimensional depth, thickness, and a natural room reverb feel to your playing.</li></ul><hr><h2 id="_4-system-requirements-distribution" tabindex="-1">4. System Requirements &amp; Distribution <a class="header-anchor" href="#_4-system-requirements-distribution" aria-label="Permalink to &quot;4. System Requirements &amp; Distribution&quot;">​</a></h2><h3 id="🖥️-system-requirements" tabindex="-1">🖥️ System Requirements <a class="header-anchor" href="#🖥️-system-requirements" aria-label="Permalink to &quot;🖥️ System Requirements&quot;">​</a></h3><ul><li><strong>Operating System:</strong> Windows 10 or Windows 11 (64-bit).</li><li><strong>Processor (CPU):</strong> Must support <strong>AVX2</strong> instruction sets (Intel Core 4th Gen / AMD Ryzen or newer) to calculate the mathematical models in real-time.</li><li><strong>RAM:</strong> 4 GB minimum.</li><li><strong>Audio Card:</strong> Audio interface with native <strong>ASIO</strong> drivers.</li></ul><h3 id="📦-distribution-all-in-one" tabindex="-1">📦 Distribution (All-in-One) <a class="header-anchor" href="#📦-distribution-all-in-one" aria-label="Permalink to &quot;📦 Distribution (All-in-One)&quot;">​</a></h3><p><strong>Midnight Rambler is 100% self-contained.</strong> It does not require loading external models, XML configs, or IR wav files separately:</p><ul><li>All neural amplifier models and cabinet profiles are <strong>embedded internally as binary resources</strong> inside the plugin binary.</li><li>Simply copy the <code>.vst3</code> file to your plugin folder or run the <code>.exe</code> standalone app to start playing.</li></ul><hr><h3 id="we-want-to-hear-your-mixes" tabindex="-1">We Want to Hear Your Mixes! <a class="header-anchor" href="#we-want-to-hear-your-mixes" aria-label="Permalink to &quot;We Want to Hear Your Mixes!&quot;">​</a></h3><p>Midnight Rambler&#39;s dynamic behavior was calibrated directly from classic record listening tests. If you&#39;ve recorded a song or mixed a track using this stompbox, we want to hear it!</p><p>Copy our contact email to share your links or feedback:</p>',45)),t("div",u,[e[0]||(e[0]=t("span",{class:"rock-email-text"},"mainstaudiolabs@gmail.com",-1)),t("button",{class:"rock-copy-btn",onClick:a},s(i.value),1)]),e[2]||(e[2]=t("p",{style:{"margin-top":"2rem","margin-bottom":"1rem"}},"If you would like to support our independent research and help us keep our plugins free, you can support us with Card, PayPal, or Cryptocurrency:",-1)),e[3]||(e[3]=t("div",null,[t("a",{href:"/support",class:"rock-btn rock-btn-primary",style:{display:"inline-block","text-align":"center"}},"Support the Lab (Ko-fi / Crypto) ☕")],-1)),e[4]||(e[4]=t("div",{class:"print-footer"},[l(" Official Website & Manual: "),t("a",{href:"https://mainstaudiolabs.github.io/midnight-rambler.html",target:"_blank"},"https://mainstaudiolabs.github.io/midnight-rambler.html")],-1))]))}});export{p as __pageData,b as default};
